import {mkdir, writeFile} from 'node:fs/promises'
import {dirname} from 'node:path'

import {stringify as stringifyYaml} from 'yaml'

import type {ProjectConfig} from '@domain/config/types'

import {getProjectConfigPath} from './loader'
import type {WriteProjectConfigFunction} from './types'

export const CONFIG_HEADER = [
    '# .crucible/forge.config.yaml',
    '# Generated by forge init — edit manually or use forge config commands',
    '',
    '',
].join('\n')

export const writeProjectConfig: WriteProjectConfigFunction = async (
    projectRoot: string,
    config: ProjectConfig,
) => {
    const configPath = getProjectConfigPath(projectRoot)

    await mkdir(dirname(configPath), {recursive: true})

    const yaml = stringifyYaml(config, {lineWidth: 120})

    await writeFile(configPath, CONFIG_HEADER + yaml, 'utf-8')

    return configPath
}
